python3 - <<'EOF'
p='src/ribbon/project_tab.rs'; s=open(p).read()
i=s.index("/// The widest the project's name gets before it is cut off.")
j=s.index("impl Ribbon {")
body=s[i:j]
s=s[:i]+s[j:]
open(p,'w').write(s)
body=body.replace("pub(super) fn project_name(cx: &App) -> AnyElement {","pub fn project_indicator(cx: &App) -> AnyElement {")
body=body.replace("/// The open project's name, a label beside the tabs, or \"No project\"; its\n/// tooltip gives the project's path.","/// The indicator: the open project's folder name, or \"No project\", with its\n/// path as the tooltip.")
head='''//! The project indicator: which project is loaded, shown as its folder's name
//! after a folder icon, or "No project" while none is. It is only a label; its
//! tooltip gives the project's full path.

use gpui_kit::assets::IconName;
use gpui_kit::component::tooltip::Tooltip;
use gpui_kit::component::{ActiveTheme as _, Icon, Sizable as _, StyledExt as _, h_flex};
use gpui_kit::prelude::FluentBuilder as _;
use gpui_kit::*;

use crate::project_directory::ProjectDirectory;

'''
open('src/project_indicator.rs','w').write(head+body)
p='src/ribbon/mod.rs'; s=open(p).read()
s=s.replace("project_tab::project_name(cx)","crate::project_indicator::project_indicator(cx)")
open(p,'w').write(s)
p='src/main.rs'; s=open(p).read(); s=s.replace("mod project_directory;","mod project_directory;\nmod project_indicator;",1); open(p,'w').write(s)
EOF
cargo build 2>&1 | grep -E "^(error|warning)" -A8 | head -30

